def get_timeout_ms(client, service):
    for path in (f"services/{service}/timeout", "defaults/timeout"):
        try:
            raw = client.get(path)
        except KeyError:
            continue
        raw = raw.strip()
        if raw.endswith("ms"):
            return int(raw[:-2])
        if raw.endswith("s"):
            return int(raw[:-1]) * 1000
        return int(raw)
    return 5000
